import type { Command } from "foldkit";
import { Ui } from "foldkit";

export const { Model } = Ui.Dialog;
export type Model = Ui.Dialog.Model;

export const { RequestedOpen } = Ui.Dialog;
export const { RequestedClose } = Ui.Dialog;
export const { CompletedShowDialog } = Ui.Dialog;
export const { CompletedCloseDialog } = Ui.Dialog;
export const { GotAnimationMessage } = Ui.Dialog;
export const { Message } = Ui.Dialog;
export type RequestedOpen = Ui.Dialog.RequestedOpen;
export type RequestedClose = Ui.Dialog.RequestedClose;
export type CompletedShowDialog = Ui.Dialog.CompletedShowDialog;
export type CompletedCloseDialog = Ui.Dialog.CompletedCloseDialog;
export type Message = Ui.Dialog.Message;

export const { Opened } = Ui.Dialog;
export const { Closed } = Ui.Dialog;
export const { OutMessage } = Ui.Dialog;
export type Opened = Ui.Dialog.Opened;
export type Closed = Ui.Dialog.Closed;
export type OutMessage = Ui.Dialog.OutMessage;

export type InitConfig = Ui.Dialog.InitConfig;
export type Commands = readonly Command.Command<Message>[];
export type InitReturn = readonly [Model, Commands];
export type UpdateReturn = ReturnType<typeof Ui.Dialog.update>;

export const { ShowDialog } = Ui.Dialog;
export const { CloseDialog } = Ui.Dialog;

export const init = (config: InitConfig): InitReturn => [
  Ui.Dialog.init(config),
  [],
];

export const { update } = Ui.Dialog;
export const { open } = Ui.Dialog;
export const { close } = Ui.Dialog;
export const { titleId } = Ui.Dialog;
export const { descriptionId } = Ui.Dialog;

export {
  backdrop,
  cancelButton,
  closeButton,
  confirmButton,
  description,
  footer,
  panel,
  root,
  title,
  trigger,
  view,
} from "./view";
export type {
  ActionInputs,
  ContainerInputs,
  DialogAttribute,
  DialogChild,
  DialogVariant,
  PanelInputs,
  RenderInfo,
  RootInputs,
  TextInputs,
  TriggerInputs,
  ViewInputs,
} from "./view";

import { Ui } from "foldkit";
import type { Attribute, ChildAttribute, Html } from "foldkit/html";
import { html } from "foldkit/html";

export type RenderInfo = Ui.Dialog.RenderInfo;
export type ViewInputs = Ui.Dialog.ViewInputs;
export type DialogChild = Html | string;
export type DialogAttribute<Message> = Attribute<Message> | ChildAttribute;
export type DialogVariant = "default" | "destructive";

export type TriggerInputs<Message> = Readonly<{
  label: string;
  onClick: Message;
  focusSelector?: string;
}>;

export type RootInputs = Readonly<{
  render: RenderInfo;
  children: readonly DialogChild[];
}>;

export type PanelInputs = Readonly<{
  render: RenderInfo;
  children: readonly DialogChild[];
}>;

export type TextInputs = Readonly<{
  model: Ui.Dialog.Model;
  children: readonly DialogChild[];
}>;

export type ContainerInputs = Readonly<{
  children: readonly DialogChild[];
}>;

export type ActionInputs<Message> = Readonly<{
  label: string;
  onClick: Message;
  variant?: DialogVariant;
}>;

const triggerClassName =
  "inline-flex items-center justify-center rounded-lg border border-gray-300 bg-white px-4 py-2 text-base font-normal text-gray-900 transition hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";

const rootClassName =
  "backdrop:bg-transparent bg-transparent p-0 open:flex items-center justify-center";

const backdropClassName =
  "fixed inset-0 bg-black/50 transition duration-150 ease-out data-[closed]:opacity-0";

const panelClassName =
  "bg-white rounded-lg p-6 max-w-md mx-auto relative shadow-xl transition duration-150 ease-out data-[closed]:opacity-0 data-[closed]:scale-95";

const titleClassName = "text-lg font-semibold text-gray-900";

const descriptionClassName = "mt-2 text-base text-gray-600";

const footerClassName = "mt-6 flex justify-end gap-2";

const closeButtonClassName =
  "rounded-lg border border-gray-300 px-4 py-2 text-base font-normal text-gray-700 transition hover:bg-gray-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-gray-500";

const defaultButtonClassName =
  "rounded-lg bg-accent-600 px-4 py-2 text-base font-normal text-white transition hover:bg-accent-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600";

const destructiveButtonClassName =
  "rounded-lg bg-red-600 px-4 py-2 text-base font-normal text-white transition hover:bg-red-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-red-600";

const actionClassName = (variant: DialogVariant): string =>
  variant === "destructive"
    ? destructiveButtonClassName
    : defaultButtonClassName;

export const { view } = Ui.Dialog;

export const trigger = <Message>({
  label,
  onClick,
  focusSelector,
}: TriggerInputs<Message>): Html => {
  const h = html<Message>();

  return h.button(
    [
      h.Type("button"),
      h.Class(triggerClassName),
      focusSelector === undefined
        ? h.OnClick(onClick)
        : h.OnClickFocus(focusSelector, onClick),
    ],
    [label]
  );
};

export const root = <Message>({ render, children }: RootInputs): Html => {
  const h = html<Message>();

  return h.dialog(
    [...render.dialog, h.Class(rootClassName)],
    render.isVisible ? children : []
  );
};

export const backdrop = <Message>(render: RenderInfo): Html => {
  const h = html<Message>();

  return h.div([...render.backdrop, h.Class(backdropClassName)], []);
};

export const panel = <Message>({ render, children }: PanelInputs): Html => {
  const h = html<Message>();

  return h.div([...render.panel, h.Class(panelClassName)], children);
};

export const title = <Message>({ model, children }: TextInputs): Html => {
  const h = html<Message>();

  return h.h2(
    [h.Id(Ui.Dialog.titleId(model)), h.Class(titleClassName)],
    children
  );
};

export const description = <Message>({ model, children }: TextInputs): Html => {
  const h = html<Message>();

  return h.p(
    [h.Id(Ui.Dialog.descriptionId(model)), h.Class(descriptionClassName)],
    children
  );
};

export const footer = <Message>({ children }: ContainerInputs): Html => {
  const h = html<Message>();

  return h.div([h.Class(footerClassName)], children);
};

export const closeButton = <Message>({
  label,
  onClick,
}: ActionInputs<Message>): Html => {
  const h = html<Message>();

  return h.button(
    [h.Type("button"), h.Class(closeButtonClassName), h.OnClick(onClick)],
    [label]
  );
};

export const cancelButton = closeButton;

export const confirmButton = <Message>({
  label,
  onClick,
  variant = "default",
}: ActionInputs<Message>): Html => {
  const h = html<Message>();

  return h.button(
    [h.Type("button"), h.Class(actionClassName(variant)), h.OnClick(onClick)],
    [label]
  );
};

import { Option } from "effect";
import { Story } from "foldkit";
import { describe, expect, test } from "vitest";

import * as Dialog from "./index";

const dialogId = "account-dialog";
const focusSelector = "#account-name";

const initModel = (): Dialog.Model => Dialog.init({ id: dialogId })[0];

const ShowAccountDialog = Dialog.ShowDialog({
  id: dialogId,
  maybeFocusSelector: Option.none(),
});

const CloseAccountDialog = Dialog.CloseDialog({ id: dialogId });

const expectSomeOutMessage = (
  maybeOutMessage: Option.Option<Dialog.OutMessage>,
  tag: Dialog.OutMessage["_tag"]
) => {
  expect(Option.isSome(maybeOutMessage)).toBe(true);

  if (Option.isSome(maybeOutMessage)) {
    expect(maybeOutMessage.value._tag).toBe(tag);
  }
};

describe("Dialog registry component", () => {
  describe(Dialog.init, () => {
    test("returns a model with no startup commands", () => {
      const [model, commands] = Dialog.init({ id: dialogId });

      expect(model.id).toBe(dialogId);
      expect(model.isOpen).toBe(false);
      expect(commands).toEqual([]);
    });

    test("preserves explicit open, animation, and focus configuration", () => {
      const [model, commands] = Dialog.init({
        id: dialogId,
        focusSelector,
        isAnimated: true,
        isOpen: true,
      });

      expect(model.isOpen).toBe(true);
      expect(model.isAnimated).toBe(true);
      expect(Option.isSome(model.maybeFocusSelector)).toBe(true);

      if (Option.isSome(model.maybeFocusSelector)) {
        expect(model.maybeFocusSelector.value).toBe(focusSelector);
      }

      expect(commands).toEqual([]);
    });
  });

  describe(Dialog.update, () => {
    test("opens a closed dialog and emits one parent-visible fact", () => {
      Story.story(
        Dialog.update,
        Story.with(initModel()),
        Story.message(Dialog.RequestedOpen()),
        Story.model((model) => {
          expect(model.isOpen).toBe(true);
        }),
        Story.Command.expectExact(ShowAccountDialog),
        Story.expectOutMessage(Dialog.Opened()),
        Story.Command.resolve(ShowAccountDialog, Dialog.CompletedShowDialog())
      );
    });

    test("does not re-emit Opened for an already-open dialog", () => {
      const [openModel] = Dialog.open(initModel());

      Story.story(
        Dialog.update,
        Story.with(openModel),
        Story.message(Dialog.RequestedOpen()),
        Story.model((model) => {
          expect(model.isOpen).toBe(true);
        }),
        Story.Command.expectNone(),
        Story.expectNoOutMessage()
      );
    });

    test("closes an open dialog and emits one parent-visible fact", () => {
      const [openModel] = Dialog.open(initModel());

      Story.story(
        Dialog.update,
        Story.with(openModel),
        Story.message(Dialog.RequestedClose()),
        Story.model((model) => {
          expect(model.isOpen).toBe(false);
        }),
        Story.Command.expectExact(CloseAccountDialog),
        Story.expectOutMessage(Dialog.Closed()),
        Story.Command.resolve(CloseAccountDialog, Dialog.CompletedCloseDialog())
      );
    });

    test("does not re-emit Closed for an already-closed dialog", () => {
      Story.story(
        Dialog.update,
        Story.with(initModel()),
        Story.message(Dialog.RequestedClose()),
        Story.model((model) => {
          expect(model.isOpen).toBe(false);
        }),
        Story.Command.expectNone(),
        Story.expectNoOutMessage()
      );
    });
  });

  describe("helper API", () => {
    test("open delegates to RequestedOpen behavior", () => {
      const [model, commands, maybeOutMessage] = Dialog.open(initModel());

      expect(model.isOpen).toBe(true);
      expect(commands).toHaveLength(1);
      expect(commands[0]?.name).toBe(ShowAccountDialog.name);
      expect(commands[0]?.args).toEqual(ShowAccountDialog.args);
      expectSomeOutMessage(maybeOutMessage, "Opened");
    });

    test("close delegates to RequestedClose behavior", () => {
      const [openModel] = Dialog.open(initModel());
      const [model, commands, maybeOutMessage] = Dialog.close(openModel);

      expect(model.isOpen).toBe(false);
      expect(commands).toHaveLength(1);
      expect(commands[0]?.name).toBe(CloseAccountDialog.name);
      expect(commands[0]?.args).toEqual(CloseAccountDialog.args);
      expectSomeOutMessage(maybeOutMessage, "Closed");
    });
  });
});

import { Option } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Dialog from "./index";

const dialogId = "account-dialog";
const titleText = "Edit account";
const descriptionText = "Make changes to your account details.";

const [initialModel] = Dialog.init({ id: dialogId });

const ShowAccountDialog = Dialog.ShowDialog({
  id: dialogId,
  maybeFocusSelector: Option.none(),
});

const CloseAccountDialog = Dialog.CloseDialog({ id: dialogId });

const view = (model: Dialog.Model): Html => {
  const h = html<Dialog.Message>();

  return h.div(
    [],
    [
      Dialog.trigger<Dialog.Message>({
        label: "Open account dialog",
        onClick: Dialog.RequestedOpen(),
      }),
      h.submodel({
        slotId: model.id,
        model,
        view: Dialog.view,
        viewInputs: {
          toView: (render) =>
            Dialog.root<Dialog.Message>({
              render,
              children: [
                Dialog.backdrop<Dialog.Message>(render),
                Dialog.panel<Dialog.Message>({
                  render,
                  children: [
                    Dialog.title<Dialog.Message>({
                      model,
                      children: [titleText],
                    }),
                    Dialog.description<Dialog.Message>({
                      model,
                      children: [descriptionText],
                    }),
                    Dialog.footer<Dialog.Message>({
                      children: [
                        Dialog.cancelButton<Dialog.Message>({
                          label: "Cancel",
                          onClick: Dialog.RequestedClose(),
                        }),
                        Dialog.confirmButton<Dialog.Message>({
                          label: "Save changes",
                          onClick: Dialog.RequestedClose(),
                        }),
                        Dialog.closeButton<Dialog.Message>({
                          label: "Close",
                          onClick: Dialog.RequestedClose(),
                        }),
                      ],
                    }),
                  ],
                }),
              ],
            }),
        },
        toParentMessage: (message) => message,
      }),
    ]
  );
};

describe("Dialog registry view helpers", () => {
  test("opens a labelled dialog from the trigger", () => {
    Scene.scene(
      { update: Dialog.update, view },
      Scene.with(initialModel),
      Scene.expect(
        Scene.role("button", { name: "Open account dialog" })
      ).toExist(),
      Scene.expect(Scene.text(titleText)).not.toExist(),
      Scene.click(Scene.role("button", { name: "Open account dialog" })),
      Scene.Command.expectExact(ShowAccountDialog),
      Scene.Command.resolve(ShowAccountDialog, Dialog.CompletedShowDialog()),
      Scene.expect(Scene.role("dialog", { name: titleText })).toExist(),
      Scene.expect(
        Scene.role("dialog", { name: titleText })
      ).toHaveAccessibleDescription(descriptionText),
      Scene.expect(Scene.role("button", { name: "Cancel" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Save changes" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Close" })).toExist()
    );
  });

  test("cancel closes the dialog", () => {
    Scene.scene(
      { update: Dialog.update, view },
      Scene.with(initialModel),
      Scene.click(Scene.role("button", { name: "Open account dialog" })),
      Scene.Command.resolve(ShowAccountDialog, Dialog.CompletedShowDialog()),
      Scene.click(Scene.role("button", { name: "Cancel" })),
      Scene.Command.expectExact(CloseAccountDialog),
      Scene.Command.resolve(CloseAccountDialog, Dialog.CompletedCloseDialog()),
      Scene.expect(Scene.text(titleText)).not.toExist()
    );
  });

  test("confirm closes the dialog", () => {
    Scene.scene(
      { update: Dialog.update, view },
      Scene.with(initialModel),
      Scene.click(Scene.role("button", { name: "Open account dialog" })),
      Scene.Command.resolve(ShowAccountDialog, Dialog.CompletedShowDialog()),
      Scene.click(Scene.role("button", { name: "Save changes" })),
      Scene.Command.expectExact(CloseAccountDialog),
      Scene.Command.resolve(CloseAccountDialog, Dialog.CompletedCloseDialog()),
      Scene.expect(Scene.text(titleText)).not.toExist()
    );
  });
});
